-- =============================================================================
-- PDI · 0036 · Motor Beta: resultados Saber 11 → Saber TyT 2016-2024
--
-- Carga el conjunto del Motor Beta en el informe Enseñanza con lo que reunió
-- Planeación en "Resultado_SaberTyT_con_Saber11.xlsx": los evaluados de Saber
-- TyT de los programas de tecnología, cruzados uno a uno con el Saber 11 que
-- presentaron antes de entrar.
--
-- Todo llega agregado: por año, nivel, programa y competencia, en rango
-- percentil dentro de la cohorte histórica de la universidad (la curva de cada
-- prueba va en benchmarks). Sin nombres, documentos ni consecutivos.
--
-- Lo que hay que saber al leerlo:
--   · Los programas no traen sede en la fuente: el conjunto se publica para
--     toda la universidad.
--   · Un puntaje 0 es una prueba no presentada o anulada y no cuenta.
--   · 1204 de 1464 evaluados tienen su Saber 11 cruzado; el valor agregado se
--     calcula solo sobre ellos.
--   · Los nombres de programa venían con tildes perdidas y caracteres dañados
--     ("GR¿FICA"): se corrigieron y se unificaron las variantes del mismo
--     programa.
--
-- Crea el bloque "saber_tyt" al final de la ficha si el informe no lo tiene.
-- Requiere 0035. Idempotente: vuelve a escribir las cifras si ya existen.
-- =============================================================================

insert into public.od_saber_tyt (report_id, key, title, description, note, benchmarks, office_id, position)
select r.id, 'saber-tyt', 'Saber TyT · Motor Beta',
  'Qué tan lejos llegan los estudiantes de tecnología entre la prueba con la que entraron (Saber 11) y la prueba con la que salen (Saber TyT).',
  'Fuente: ICFES, resultados Saber TyT cruzados con Saber 11 por estudiante. Cada puntaje se lee como su percentil dentro de la cohorte histórica de la UDES en esa prueba, porque las escalas son distintas (Saber 11 califica cada módulo de 0 a 100 y su global de 0 a 500; Saber TyT, de 0 a 200). El valor agregado es el percentil de salida menos el de entrada. No es una equivalencia entre pruebas: compara posiciones dentro de cada una.',
