from public.od_reports r
where r.slug = 'ensenanza'
on conflict (report_id, key) do update
  set benchmarks = excluded.benchmarks;

delete from public.od_saber_tyt_results res
using public.od_saber_tyt t, public.od_reports r
where res.tyt_id = t.id and t.report_id = r.id and r.slug = 'ensenanza' and t.key = 'saber-tyt';

