insert into public.od_report_blocks (report_id, kind, ref_id, position, visible, settings)
select r.id, 'saber_tyt', null,
  coalesce((select max(b.position) + 1 from public.od_report_blocks b where b.report_id = r.id), 0),
  true, '{}'::jsonb
from public.od_reports r
where r.slug = 'ensenanza'
  and not exists (select 1 from public.od_report_blocks b where b.report_id = r.id and b.kind = 'saber_tyt');
